window.products.push({"id":298080,"name":"6Pcs Wide Mouth Mushroom Liquid Culture Lid Grain Spawn Cultivation Mason Jar Lid with 0.2 micron PTFE Syringe Filter & 20mm Self Healing Injection Po","category":"homeandappliances","retail price":23.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71MWQBDQkyL._AC_SL1500_.jpg","description":"Quantity:6pcs Colour:Silver Lid Material: Tinplate Lid diameter:86mm Fit for all Wide Mouth jars Used for making mushroom liquid cultures. The Lid comes with a self healing injection for injecting culture and a PTFE syringe filter for avoid contamination . These lids can be used in a microwave, autoclave or pressure cooker. Our professional grade autoclavable wide mouth jar lids are built to be lab-quality, and made specifically for liquid culturing . Leave the lids a quarter turn loose while in the pressure cooker so air can escape, otherwise the injection ports will pop out.","images":["https://m.media-amazon.com/images/I/71MWQBDQkyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Biomed Solutions","source_asin":"B08P5MNZV2","category_path":"Home & Kitchen"},"sku":"BM-298080","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08P5MNZV2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08P5MNZV2","price_pending":true,"merchant_ready":false});
